import { toOasOperationEntry } from 'jsr:@skmtc/core@0.28.3'
import { defineAndRegister, createVariable } from 'jsr:@skmtc/lang-typescript@0.12.17'
import { MockRoute } from './MockRoute.ts'
import { MockRoutesList } from './MockRoutesList.ts'
import { toEnrichmentSchema, type EnrichmentSchema } from './enrichments.ts'
import denoJson from '../deno.json' with { type: 'json' }

export const MswEntry = toOasOperationEntry<EnrichmentSchema>({
  id: denoJson.name,

  toEnrichmentSchema,

  transform: ({ context, operation }) => {
    const insertedRoute = context.insertOperation({ projection: MockRoute, operation: operation })

    const { exportPath } = insertedRoute.settings

    const route = insertedRoute.toName()

    if (!route) {
      return
    }

    const existingRoutesList = context.findDefinition({ name: 'toRoutesList', exportPath })

    if (existingRoutesList?.value instanceof MockRoutesList) {
      existingRoutesList.value.add(route)
      return
    }

    const routesList = defineAndRegister(context, {
      identifier: createVariable('toRoutesList'),
      value: new MockRoutesList({ context }),
      destinationPath: exportPath
    })

    routesList.value.add(route)
  }
})

import type { OasOperationProjectionConstructorArgs } from 'jsr:@skmtc/core@0.28.3'
import { match } from 'npm:ts-pattern@^5.8.0'
import { QueryEndpoint } from './QueryEndpoint.ts'
import { PaginatedQueryEndpoint } from './PaginatedQueryEndpoint.ts'
import { MutationEndpoint } from './MutationEndpoint.ts'
import { TanstackQueryBase } from './base.ts'
import type { EnrichmentSchema } from './enrichments.ts'
import { isListResponse } from './listFns.ts'

export class TanstackQuery extends TanstackQueryBase {
  client: PaginatedQueryEndpoint | QueryEndpoint | MutationEndpoint

  constructor({ context, operation, settings }: OasOperationProjectionConstructorArgs<EnrichmentSchema>) {
    super({ context, operation, settings })

    this.client = match(operation)
      .with({ method: 'get' }, () => {
        return isListResponse(operation)
          ? new PaginatedQueryEndpoint({
              context,
              operation,
              settings
            })
          : new QueryEndpoint({
              context,
              operation,
              settings
            })
      })
      .otherwise(() => {
        return new MutationEndpoint({
          context,
          operation,
          settings
        })
      })
  }

  override toString(): string {
    return this.client.toString()
  }
}

