  return new ContentSettings<EnrichmentType>({
    identifier: args.projection.lang.toIdentifier({
      name: args.projection.toIdentifierName({
        webhook: args.webhook,
        enrichments,
        variant
      }),
      ...args.projection.toIdentifierType(args.webhook, this)
