    const { path, method } = this.operation

    const parameters = List.toParams([
      ...this.pathParams.map(({ name, type }) => `${name}: ${type}`),
      ...(this.requestBodyName ? [`body: z.infer<typeof ${this.requestBodyName}>`] : [])
    ])

    const options = new List(
      [
        `method: '${method.toUpperCase()}'`,
        ...(this.requestBodyName
          ? [`headers: { 'Content-Type': 'application/json' }`, `body: JSON.stringify(body)`]
          : [])
      ],
      { separator: ',\n      ' }
    )

    return `async ${this.name}${parameters} {
    const res = await fetch(\`${toPathTemplate(path)}\`, {
      ${options}
    })

    if (!res.ok) {
      throw new Error(await res.text())
    }

    return ${this.responseName}.parse(await res.json())
  }`
  }
}
